import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/reports/*")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL"); // e.g. jdbc:postgresql://db:5432/analytics
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String pathInfo = req.getPathInfo();
        if (pathInfo == null || pathInfo.equals("/")) {
            resp.sendError(400, "Missing report ID");
            return;
        }

        String reportId = pathInfo.substring(1);
        String format = req.getParameter("format");
        String dateRange = req.getParameter("range");

        // Validate format parameter
        if (format != null && !format.matches("^(csv|json|xml)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Build query based on parameters
        String query = buildReportQuery(reportId, dateRange);
        log.info("Executing report query for ID: " + reportId);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) sb.append(",\n");
                sb.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) sb.append(", ");
                    sb.append("\"").append(meta.getColumnName(i)).append("\": ");
                    sb.append("\"").append(rs.getString(i)).append("\"");
                }
                sb.append("}");
                first = false;
            }
            sb.append("\n]");
            resp.getWriter().write(sb.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String reportId, String dateRange) {
        // Base query construction
        String baseTable = "report_data_" + reportId;
        String query = "SELECT * FROM " + baseTable;

        if (dateRange != null && !dateRange.isEmpty()) {
            // dateRange expected as "2024-01-01,2024-12-31"
            String[] parts = dateRange.split(",");
            if (parts.length == 2) {
                query += " WHERE created_at BETWEEN '" + parts[0] + "' AND '" + parts[1] + "'";
            }
        }

        query += " ORDER BY created_at DESC LIMIT 1000";
        return query;
    }

    @Override
    protected void doDelete(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String pathInfo = req.getPathInfo();
        if (pathInfo == null) {
            resp.sendError(400);
            return;
        }

        String reportId = pathInfo.substring(1);
        String query = "DELETE FROM report_metadata WHERE report_id = '" + reportId + "'";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {
            int affected = stmt.executeUpdate(query);
            resp.getWriter().write("{\"deleted\": " + affected + "}");
        } catch (SQLException e) {
            log.warning("Delete failed: " + e.getMessage());
            resp.sendError(500, "Delete failed");
        }
    }
}
